From 73de7bf518b739c89e2d94141b13120955c36201 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 23:06:41 +0100
Subject: [PATCH] shell: add a global Ctrl+Alt+T shortcut to open the default
 terminal

The only Ctrl+Alt+T shortcut came from Konsole's own desktop file, so it
always opened Konsole even when another terminal was set as default. Add
an Open Terminal action to plasmashell that launches the default one.

BUG: 464004
---
 containmentactions/contextmenu/menu.cpp |  1 +
 shell/CMakeLists.txt                    |  5 +----
 shell/shellcorona.cpp                   | 18 ++++++++++++++++++
 3 files changed, 20 insertions(+), 4 deletions(-)

diff --git a/containmentactions/contextmenu/menu.cpp b/containmentactions/contextmenu/menu.cpp
index 7097e442cf..eac8e203d3 100644
--- a/containmentactions/contextmenu/menu.cpp
+++ b/containmentactions/contextmenu/menu.cpp
@@ -111,6 +111,7 @@ void ContextMenu::restore(const KConfigGroup &config)

         m_openTerminalAction = new QAction(i18n("Open Terminal"), this);
         m_openTerminalAction->setIcon(QIcon::fromTheme(u"utilities-terminal-symbolic"_s));
+        m_openTerminalAction->setShortcut(KGlobalAccel::self()->globalShortcut(u"plasmashell"_s, u"open terminal"_s).value(0));
         connect(m_openTerminalAction, &QAction::triggered, this, &ContextMenu::openTerminal);

         m_lockScreenAction = new QAction(i18nc("plasma_containmentactions_contextmenu", "Lock Screen"), this);
diff --git a/shell/CMakeLists.txt b/shell/CMakeLists.txt
index 05393e8838..0ae2bb2f7b 100644
--- a/shell/CMakeLists.txt
+++ b/shell/CMakeLists.txt
@@ -118,6 +118,7 @@ target_link_libraries(plasmashell PRIVATE
  KF6::I18n
  KF6::I18nQml
  KF6::KIOCore
+ KF6::KIOGui
  KF6::Package
  KF6::Notifications
  KF6::Service
@@ -148,10 +149,6 @@ endif()
 target_include_directories(plasmashell PRIVATE "${CMAKE_BINARY_DIR}")
 target_compile_definitions(plasmashell PRIVATE -DPROJECT_VERSION="${PROJECT_VERSION}")

-if(PROJECT_VERSION_PATCH GREATER_EQUAL 80 OR PROJECT_VERSION_MINOR GREATER_EQUAL 80)
-    target_link_libraries(plasmashell PRIVATE KF6::KIOGui)
-endif()
-
 configure_file(org.kde.plasmashell.desktop.cmake ${CMAKE_CURRENT_BINARY_DIR}/org.kde.plasmashell.desktop @ONLY)

 install(TARGETS plasmashell ${KDE_INSTALL_TARGETS_DEFAULT_ARGS})
diff --git a/shell/shellcorona.cpp b/shell/shellcorona.cpp
index 51bde18ac6..dda0bf7416 100644
--- a/shell/shellcorona.cpp
+++ b/shell/shellcorona.cpp
@@ -20,6 +20,7 @@
 #include <QDBusPendingCallWatcher>
 #include <QDBusReply>
 #include <QDebug>
+#include <QDir>
 #include <QFile>
 #include <QJsonArray>
 #include <QJsonDocument>
@@ -38,6 +39,7 @@
 #include <KMessageBox>
 #include <KPackage/PackageLoader>
 #include <KSycoca>
+#include <KTerminalLauncherJob>
 #include <KWindowSystem>

 #include <Plasma/Plasma>
@@ -284,6 +286,22 @@ void ShellCorona::init()
     KGlobalAccel::self()->setGlobalShortcut(cyclePanelFocusAction, Qt::META | Qt::ALT | Qt::Key_P);
     connect(cyclePanelFocusAction, &QAction::triggered, this, &ShellCorona::slotCyclePanelFocus);

+    auto *openTerminalAction = new QAction(this);
+    setAction(QStringLiteral("open terminal"), openTerminalAction);
+    openTerminalAction->setText(i18n("Open Terminal"));
+    openTerminalAction->setIcon(QIcon::fromTheme(QStringLiteral("utilities-terminal")));
+    KGlobalAccel::self()->setGlobalShortcut(openTerminalAction, Qt::CTRL | Qt::ALT | Qt::Key_T);
+    connect(openTerminalAction, &QAction::triggered, this, [] {
+        if (!KAuthorized::authorizeAction(QStringLiteral("shell_access"))) {
+            return;
+        }
+        // Pick up a default terminal changed since plasmashell started
+        KSharedConfig::openConfig()->reparseConfiguration();
+        auto job = new KTerminalLauncherJob(QString());
+        job->setWorkingDirectory(QDir::homePath());
+        job->start();
+    });
+
     unload();
     /*
      * we want to make an initial load once we have loaded the activities _IF_ KAMD is running
-- 
2.53.0
